<template><div class="ingredient-choice"><McItem v-if="chosen" :id="chosen" :count="chosenStack?.count||ingredient.count||1" :stack="chosenStack" :size="36"/><span v-else class="ingredient-empty">—</span><small v-if="chosen" class="ingredient-label">{{nameOf(catalog?.items[chosen]||{id:chosen},lang)}}</small><small v-if="ingredient.tag" :title="'#'+ingredient.tag">{{en?'Any matching':'任一匹配'}}<br><code>#{{ingredient.tag}}</code></small><small v-else-if="ingredient.alternatives">{{en?'Any of '+ids.length:'任选其一 · '+ids.length}}</small><select v-if="ids.length>1" v-model="selected" :aria-label="en?'Accepted ingredient':'可用材料'"><option v-for="id in ids" :key="id" :value="id">{{nameOf(catalog?.items[id]||{id},lang)}}</option></select></div></template>
<script setup lang="ts">
import{ref,computed,onMounted}from'vue';import{useData}from'vitepress';import{getData,nameOf}from'../lib/wiki';import McItem from'./McItem.vue';
const props=defineProps<{ingredient:any}>();const{lang}=useData();const en=computed(()=>lang.value.startsWith('en'));const catalog=ref<any>(null),selected=ref('');
const ids=computed(()=>{const i=props.ingredient;if(i.id)return[i.id];if(i.tag)return catalog.value?.tags[i.tag]??[];return(i.alternatives??[]).flatMap((v:any)=>v.id?[v.id]:catalog.value?.tags[v.tag]??[])});const chosen=computed(()=>selected.value||ids.value[0]);const chosenStack=computed(()=>{const i=props.ingredient;return i.alternatives?.find((v:any)=>v.id===chosen.value)||{...i,id:chosen.value}});onMounted(async()=>{catalog.value=await getData()});
</script>
